package com.hbm.machine.forcefield;
import java.util.List;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.wrapper.*;import net.neoforged.neoforge.network.IContainerFactory;import net.neoforged.neoforge.registries.*;
public final class ForceFieldContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");
 public static final DeferredBlock<ForceFieldBlock> BLOCK=BLOCKS.register("machine_forcefield",ForceFieldBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem(BLOCK);public static final DeferredItem<ForceFieldUpgradeItem> RADIUS=ITEMS.register("upgrade_radius",()->new ForceFieldUpgradeItem(true)),HEALTH=ITEMS.register("upgrade_health",()->new ForceFieldUpgradeItem(false));
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<ForceFieldBlockEntity>> ENTITY=ENTITIES.register("forcefield",()->BlockEntityType.Builder.of(ForceFieldBlockEntity::new,BLOCK.get()).build(null));public static final DeferredHolder<MenuType<?>,MenuType<ForceFieldMenu>> MENU=MENUS.register("forcefield",()->new MenuType<>((IContainerFactory<ForceFieldMenu>)ForceFieldMenu::new,FeatureFlags.DEFAULT_FLAGS));
 public static ResourceLocation id(String path){return ResourceLocation.fromNamespaceAndPath("hbm",path);}
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MENUS.register(bus);bus.addListener(ForceFieldControl::register);bus.addListener(ForceFieldContent::capabilities);}
 private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY.get(),(field,side)->side==null?new InvWrapper(field):new SidedInvWrapper(field,side));}
 public static List<ItemStack> creativeStacks(String tab){return tab.equals("missile")?List.of(new ItemStack(ITEM.get())):tab.equals("control")?List.of(new ItemStack(RADIUS.get()),new ItemStack(HEALTH.get())):List.of();}
 private ForceFieldContent(){}
}
